      "diagnosticSteps": [
        "On supported Pixel phones, open the Pixel Diagnostics app (or use Google’s current diagnostic entry method for that model) and run the battery, charging, display, touch and connectivity checks.",
        "For a Pixel that will not start, connect a compatible USB-C charger and allow a deeply discharged battery time to respond; use Google’s model-specific no-power steps before attempting any reset.",
        "For app-related freezes, use Android Safe Mode and compare behaviour. If the fault persists in Safe Mode, back up the phone and contact Pixel support with the exact model and Android build."
      ],
