        "For a computer that cannot load Windows, power on and tap F12, then select Diagnostics where available. Record any ePSA error code and validation code.",
        "Check Service Tag and exact Dell model before downloading BIOS, drivers or battery replacements. Do not run a BIOS update while power is unstable."
